import {pythonLink} from '../python-links.mjs';
import {VERSION,STORAGE_KEY,STEPS,freshState,restoreState,growthScenario,PRACTICE,ASSESSMENTS,checkAnswer,grade,invalidate,pairedInflationRuns} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageOK=true,page='start';
try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}
const value=id=>state.fields[id]??'',money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n),complete=()=>STEPS.every(([id])=>state.done[id]);
function persist(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';updateNav();if(page==='finish'&&$('#completion-summary'))$('#completion-summary').innerHTML=finishSummary();}
function updateNav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#navigation').innerHTML=STEPS.map(([id,title,time],i)=>`<a href="#${id}" class="${state.done[id]?'done':''}" ${page===id?'aria-current="step"':''}><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':String(i+1).padStart(2,'0')}</span><span>${title}<small>${time} min${state.done[id]?' · complete':''}</small></span></a>`).join('');$('#progress-label').textContent=`${n} of 8 steps complete`;$('#progress-percent').textContent=`${Math.round(n/8*100)}%`;$('#progress').value=n;}
function announce(text){$('#announcement').textContent=text;}
function feedback(id,text,error=false){const el=$('#'+id);el.innerHTML=text;el.className='feedback'+(error?' error':'');el.setAttribute('tabindex','-1');el.focus();}
function field(id,label,{type='text',placeholder='',defaultValue='',min,max}={}){const v=state.fields[id]??defaultValue;return `<label class="field" for="${id}">${label}</label>${type==='textarea'?`<textarea data-save id="${id}" placeholder="${esc(placeholder)}">${esc(v)}</textarea>`:`<input data-save id="${id}" type="${type}" ${type==='number'?'step="any"':''} ${min===undefined?'':`min="${min}"`} ${max===undefined?'':`max="${max}"`} value="${esc(v)}" placeholder="${esc(placeholder)}">`}`;}
function check(id,label){return `<label class="option"><input data-save type="checkbox" id="${id}" ${value(id)?'checked':''}><span>${label}</span></label>`;}
function confidence(id){return `<label class="field" for="${id}">Confidence (ungraded)</label><select data-save id="${id}"><option value="">Choose if useful</option>${['Unsure','Somewhat confident','Confident'].map(v=>`<option ${value(id)===v?'selected':''}>${v}</option>`).join('')}</select>`;}
function heading(eyebrow,title,lead){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p>`;}
function bottom(){const i=STEPS.findIndex(([id])=>id===page);return `<div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<a href="../index.html#finish">← Chapter 1</a>'}${i<7?`<div><small>Up next</small><a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]} →</a></div>`:'<a href="#start">Chapter overview ↑</a>'}</div>`;}
function practice(step){const l=LESSONS[step];return heading(l.eyebrow,l.title,l.lead)+`<p class="mini"><strong>Your objective:</strong> ${l.objective}</p>`+l.body+`<section class="panel"><h2>Work it through. Then transfer.</h2><p>${l.transfer}</p><p class="mini">Enter numbers without £ or %. Use a minus sign for a loss. Round pound values and requested percentages to two decimals; extra precision is accepted within tolerance. A calculator is welcome.</p>${PRACTICE[step].map((q,i)=>`<div class="practice-item">${field(q.id,`${i+1}. ${q.title}`,{type:'number'})}<div class="actions"><button data-action="practice" data-question="${q.id}">Check calculation ${i+1}</button><details class="hint"><summary>Show a hint</summary><p>${q.hint}</p></details></div><div id="feedback-${q.id}" class="feedback" role="status">${state.checked[q.id]?'Correct. '+q.why:''}</div></div>`).join('')}${confidence(step+'Confidence')}<div class="explain-box"><h3>Explain and revise.</h3><p>${l.reflection}</p>${field(step+'Reflection','Your explanation or correction',{type:'textarea',placeholder:'My calculation shows … I corrected or checked …'})}${check(step+'Criteria',l.criteria)}<div class="actions"><button data-action="save-step" data-step="${step}">Save this step</button></div><div id="feedback-${step}" class="feedback" role="status">${state.done[step]?'Step complete. Checked calculations and reflection saved.':''}</div></div></section><p class="mini">Suggested pacing: 8–10 minutes reading and predicting, 10–15 calculating and correcting, 5 explaining. These are study allowances, not validated learner timings.</p>`;}
function start(){return `<div class="hero"><div class="hero-copy"><div class="eyebrow">CHAPTER 02 · FINANCIAL MATHEMATICS</div><h1>Make the numbers<br><em>comparable.</em></h1><p class="lead">A bigger balance is only part of the story. Learn to account for cash payments, time and the buying power of money.</p><div class="pill-row"><span class="pill">About 3 hours</span><span class="pill">No installation</span><span class="pill">Calculator welcome</span></div><a class="chapter-link" href="#returns">Begin with a return →</a></div><div class="hero-visual"><div class="visual-head"><span>THE SAME £1,000 · THREE VIEWS</span><span class="visual-tag">WORKED EXAMPLE</span></div><div class="symbol" aria-hidden="true" style="margin-top:25px">£ → t → £</div><p><strong>£1,000 today</strong><br>5% annual growth for 10 years<br><strong>£1,628.89 nominal</strong><br>With 3% annual inflation:<br><strong>£1,212.05 in today's buying power</strong></p><p class="chart-caption">Assumed constant rates. No fees, taxes or extra deposits. An illustration, not a forecast.</p></div></div><div class="section-line"><h2>One calculation. One clear meaning.</h2><span class="meta">FOUNDATION SERIES · 02 / 10</span></div><div class="cards"><article class="card"><span class="card-number">01</span><h3>Include the cash</h3><p>Distinguish price change from total return, then compound successive returns.</p></article><article class="card"><span class="card-number">02</span><h3>Respect the date</h3><p>Move values forward or discount each future payment to the same date.</p></article><article class="card"><span class="card-number">03</span><h3>Label the pounds</h3><p>Separate nominal balances, purchasing power and discounted present values.</p></article></div><section class="panel"><h2>Your workspace is ready.</h2><p>Chapter 1 introduced a fair comparison. Here you learn the arithmetic behind that comparison. You can take this chapter independently: each symbol and convention is explained, and no coding or external dataset is needed.</p><ol class="step-list"><li>Keep a calculator or a sheet of paper beside the browser. For powers, look for ^ or xʸ.</li><li>Use the percentage bridge below if needed. All chapter rates are annual effective rates unless the example says otherwise.</li><li>Your Chapter 2 answers save on this browser, separately from Chapter 1. The export button downloads a record; it does not provide cross-device import.</li><li>Visit any step, pause freely, or use the <a href="guide.html">complete printable text route</a>. There is no time limit.</li></ol><details class="hint"><summary>A quick percentage bridge</summary><p>5% = 0.05. Increasing £100 by 5% means multiplying by 1.05, giving £105. A return of −5% means multiplying by 0.95, giving £95. Try £200 increasing by 3%: 200 × 1.03 = £206.</p><p>Multiplying by 1.05 twice is 1.05². To reverse it, divide by 1.05². An exponent 1/2 means a square root. Use a calculator if these operations are new.</p></details>${check('setup','I can enter numerical answers, use a calculator for powers, and locate hints, Export and Privacy & reset.')}<div class="actions"><button data-action="setup">Confirm setup & continue →</button></div><div id="feedback-start" class="feedback" role="status"></div></section><div class="callout"><strong>Completion is based on evidence.</strong><p>Check every lesson calculation, save a short explanation, run a controlled inflation comparison in the lab, pass the independent check and save a calculation card. Free-text work is self-reviewed against criteria. The app does not certify the quality of research reasoning or award an accredited credential. Total proposed study time is 180 minutes; learner timing remains untested.</p></div>`;}
function lab(){const latest=state.runs.at(-1);return heading('STEP 06 · 35 MINUTES','Change one input.<br>Explain the difference.','Predict first, keep a log, and check the numbers. Watch how nominal money and purchasing power answer different questions.')+`<div class="callout"><strong>Hypothetical growth model</strong><p>A single time-0 deposit, no later deposits or withdrawals, constant annual effective growth and inflation, annual reinvestment, no fees or taxes. The model has no volatility, default or uncertainty. The supplied future payment is a separate time-n cash flow discounted at the chosen growth rate as an illustrative opportunity rate.</p></div><section class="panel"><h2>1. Predict, then set your assumptions.</h2><p>Keep all inputs fixed except inflation. Predict which outputs should change. Run the same setup twice with different inflation assumptions to isolate their effect.</p>${field('prediction','Your prediction and reason',{type:'textarea',placeholder:'If only inflation rises, I expect the nominal amount to … and buying power to …'})}${confidence('labConfidence')}<div class="growth-inputs" style="margin-top:25px">${[['principal','Starting amount (£)',1000,1,1e6],['rate','Annual effective growth (%)',5,0,25],['inflation','Annual inflation (%)',3,0,20],['years','Whole years',10,1,40],['goal','Separate future payment (£)',2000,1,1e7]].map(([id,l,d,min,max])=>`<div>${field(id,l,{type:'number',defaultValue:d,min,max})}</div>`).join('')}</div><p class="mini">Bounds keep the classroom model manageable; they are not estimates of reasonable or suitable investment outcomes. This lab permits nonnegative nominal growth, while earlier return exercises include losses.</p><div class="actions"><button data-action="run">Run the growth model ↗</button><button data-action="defaults" class="secondary">Reset inputs</button></div><div id="feedback-run" class="feedback" role="status"></div>${latest?results(latest):'<p class="empty">Your first result will appear here. Make a prediction before running.</p>'}</section><section class="panel"><h2>2. Verify, compare and revise.</h2><p>For your latest run, calculate its nominal ending balance by hand: starting amount × (1 + growth rate / 100)<sup>years</sup>. Use the inputs recorded in the result, even if you have since edited a control.</p>${field('hand','Latest nominal ending balance (£)',{type:'number'})}<div class="actions"><button data-action="hand">Check my hand calculation</button></div><div id="feedback-hand" class="feedback" role="status">${state.fields.handVerified?'Latest nominal ending value checked.':''}</div><p style="margin-top:25px">Record two runs with identical starting amount, growth rate, years and future payment, but different inflation. Compare the nominal ending balance, starting-year buying power and discounted value of the separate payment.</p>${field('labReflection','My comparison, correction and model limitation',{type:'textarea',placeholder:'Only inflation changed … The nominal balance … The buying power … One limitation is …'})}<details class="hint"><summary>Self-review after your comparison</summary><p>Changing only inflation changes purchasing power and the real annual rate. It does not change nominal compound growth, simple-interest growth, or the present value discounted at the unchanged nominal opportunity rate. The latter is a different question from inflation-adjusted buying power. All of these statements are conditional on this fixed-rate model.</p></details><div class="actions"><button data-action="save-lab">Save lab evidence</button><button data-action="csv" class="secondary">Download all runs (CSV)</button></div><div id="feedback-lab" class="feedback" role="status">${state.done.lab?'Lab complete: paired inflation runs, hand check and reflection saved.':''}</div></section><section class="panel"><h2>Every run, not just a favourite.</h2><p class="mini">Reset inputs keeps this log. Privacy & reset deletes Chapter 2 progress. Outputs retain full precision; displayed currency rounds to pennies.</p><div class="table-wrap">${runTable()}</div></section>`;}
function results(r){const max=Math.max(...r.rows.map(p=>Math.max(p.nominal,p.real))),X=y=>45+y/r.years*355,Y=v=>175-v/max*140;const path=key=>r.rows.map(p=>`${X(p.year)},${Y(p[key])}`).join(' ');return `<div class="results-heading"><span class="badge">RUN ${state.runs.indexOf(r)+1} · HYPOTHETICAL</span><h2 style="margin-top:15px">Same money. Different date bases.</h2><p class="result-note">Recorded inputs: ${money(r.principal)}, ${r.rate}% annual growth, ${r.inflation}% inflation, ${r.years} years. Separate future payment: ${money(r.goal)}.</p><div class="metrics"><div class="metric"><span>Nominal ending balance</span><strong>${money(r.nominal)}</strong></div><div class="metric"><span>Buying power in starting-year pounds</span><strong>${money(r.real)}</strong></div><div class="metric"><span>Simple-interest comparison</span><strong>${money(r.simple)}</strong></div><div class="metric"><span>Present value of separate ${money(r.goal)} payment</span><strong>${money(r.goalPV)}</strong></div></div><p>Exact real annual return: <strong>${r.realRate.toFixed(2)}%</strong>. Present value above discounts the separate payment at ${r.rate}%, not at inflation.</p><svg class="growth-chart" viewBox="0 0 440 230" role="img" aria-labelledby="growth-title growth-desc"><title id="growth-title">Nominal balance and starting-year purchasing power</title><desc id="growth-desc">From year 0 to ${r.years}, nominal balance changes from ${money(r.principal)} to ${money(r.nominal)}. Purchasing power ends at ${money(r.real)}. The complete yearly data are in the table below.</desc><path d="M45 30V175H405" stroke="#9aab91" fill="none"/><text x="8" y="20" font-size="11" fill="#38523f">£</text><text x="18" y="179" font-size="10" fill="#38523f">0</text><text x="45" y="199" font-size="11" fill="#38523f">Year 0</text><text x="350" y="199" font-size="11" fill="#38523f">Year ${r.years}</text><text x="45" y="22" font-size="10" fill="#38523f">Scale maximum ${money(max)}</text><polyline points="${path('nominal')}" fill="none" stroke="#245c4b" stroke-width="3"/><polyline points="${path('real')}" fill="none" stroke="#735b30" stroke-width="3" stroke-dasharray="6 4"/></svg><p class="mini">Solid green: nominal pounds. Dashed brown: starting-year buying power. Values are also provided in text and the table.</p><details><summary>Show every year as a table</summary><div class="table-wrap"><table><caption>Year-by-year calculation, no external cash flows</caption><thead><tr><th>Year</th><th>Nominal balance (£)</th><th>Simple interest (£)</th><th>Starting-year buying power (£)</th></tr></thead><tbody>${r.rows.map(p=>`<tr><td>${p.year}</td><td>${money(p.nominal)}</td><td>${money(p.simple)}</td><td>${money(p.real)}</td></tr>`).join('')}</tbody></table></div></details></div>`;}
function runTable(){return state.runs.length?`<table><caption>Hypothetical model runs</caption><thead><tr><th>Run</th><th>Start</th><th>Growth / inflation</th><th>Years</th><th>Nominal end</th><th>Buying power</th><th>Future payment / its PV</th></tr></thead><tbody>${state.runs.map((r,i)=>`<tr><td>${i+1}</td><td>${money(r.principal)}</td><td>${r.rate}% / ${r.inflation}%</td><td>${r.years}</td><td>${money(r.nominal)}</td><td>${money(r.real)}</td><td>${money(r.goal)} / ${money(r.goalPV)}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">No experiments recorded yet.</p>';}
function quiz(){const set=Number(value('quizSet')||0)%2,qs=ASSESSMENTS[set],last=state.attempts.at(-1);return heading('STEP 07 · 20 MINUTES','Do the calculation.<br>State its meaning.','Use your own workings on a new set of numbers. A calculator is allowed; the reasoning still matters.')+`<div class="callout"><strong>Criteria before you begin</strong><p>Eight questions. At least 7/8 correct, including cumulative return (3), real return (7) and the claim about evidence (8). Round all pound values and requested percentage results to two decimals; extra precision is accepted. A submitted pass plus a specific feedback response completes this step. No time limit. This is formative self-study; answers are checked locally and there is no accredited score.</p></div><section class="panel"><h2>Independent case ${set?'B':'A'}</h2><p class="mini">${state.attempts.length} submitted attempts. Both cases use annual effective rates, end-year payments and no external deposits, fees or taxes.</p>${qs.map((q,i)=>q.type==='number'?`<div class="quiz-item"><label for="quiz-${q.id}">${i+1}. ${q.title}</label><input data-save id="quiz-${q.id}" type="number" step="any" value="${esc(value('quiz-'+q.id))}"></div>`:`<fieldset class="question"><legend>${i+1}. ${q.title}</legend><div class="options">${q.options.map((o,j)=>`<label class="option"><input data-save type="radio" name="quiz-${q.id}" value="${j}" ${String(value('quiz-'+q.id))===String(j)?'checked':''}><span>${o}</span></label>`).join('')}</div></fieldset>`).join('')}${confidence('quizConfidence')}<div class="actions"><button data-action="grade">Check independent answers</button><button data-action="switch" class="secondary">Switch to case ${set?'A':'B'}</button></div><div id="feedback-assessment" class="feedback" role="status">${last?.set===set&&!state.fields.quizDirty?quizFeedback(last):''}</div></section><section class="panel"><h2>Respond to the feedback.</h2><p>Correct a mistaken method, then resubmit your answers. If you passed first time, explain a tempting wrong approach and why you rejected it. Record one specific change or check. Switching cases clears current inputs but retains submitted attempts; there are only two fixed cases.</p>${field('quizRevision','My correction and next check',{type:'textarea',placeholder:'I first … I corrected or checked … because …'})}<div class="actions"><button data-action="revision">Save my feedback response</button></div><div id="feedback-revision" class="feedback" role="status"></div></section>`;}
function quizFeedback(a){return `<strong>${a.score}/8 · ${a.passed?'Checked answers passed':'Revise and try again'}</strong><p>${a.passed?'Save a specific feedback response below.':'You need 7/8 and questions 3, 7 and 8 correct. Use the explanations, correct the method and resubmit.'}</p><ol>${ASSESSMENTS[a.set].map((q,i)=>`<li><strong>${a.details[i].correct?'Correct':'Revisit'}:</strong> ${q.why}</li>`).join('')}</ol>`;}
function finishSummary(){return `<h2>Your chapter evidence</h2>${STEPS.map(([id,t])=>`<div class="status-row"><a href="#${id}">${t}</a><span>${state.done[id]?'✓ Complete':'To finish'}</span></div>`).join('')}<div class="callout"><strong>${complete()?'Chapter 2 complete.':'Finish the remaining evidence at your pace.'}</strong><p>${complete()?'You can now distinguish return, compound growth, present value and purchasing power. <a href="../chapter-03/">Continue to Chapter 3: financial data and tools →</a> Export your record before changing devices.':'Your card does not automatically pass the calculations or independent check. Completion is a formative learning record, not a credential.'}</p></div>`;}
function finish(){return heading('STEP 08 · 10 MINUTES','Leave a trail<br>someone can follow.','A useful calculation is reproducible: inputs, dates, units, method and limitations belong beside the result.')+`<section class="panel"><h2>Your calculation card</h2><p>Use one lab run or a worked bond example. State what you calculated, how you checked it, and what it does not show. Free text is self-reviewed; the app checks completeness, not the quality of your explanation.</p>${field('cardMethod','1. Inputs, dates, formula and result',{type:'textarea',placeholder:'My run used … The rate is annual effective … The result in … pounds is …'})}${field('cardCheck','2. Hand check and the comparison that matters',{type:'textarea',placeholder:'I checked … The comparison holds … fixed and changes …'})}${field('cardLimits','3. Limit and correction after feedback',{type:'textarea',placeholder:'This assumes … I revised … because …'})}${check('cardCriteria','I labelled percentage versus pounds, nominal versus real value, the time basis, and the assumptions; I described a specific check or correction.')}<details><summary>Self-review with an exemplar after drafting</summary><p>“With £1,000 at time 0, 5% annual effective growth and 3% inflation for 10 years, no deposits or costs, I calculate £1,628.89 nominal and £1,212.05 of starting-year buying power. I checked 1,000 × 1.05¹⁰ by calculator and divided by 1.03¹⁰ for real value. Raising only inflation leaves nominal growth unchanged. I replaced ‘guaranteed savings’ with ‘conditional model output’ because the rate is assumed.”</p></details><div class="actions"><button data-action="card">Save my calculation card</button><button data-action="export" class="secondary">Export Chapter 2 record ↗</button></div><div id="feedback-finish" class="feedback" role="status">${state.card?'Calculation card saved.':''}</div></section><section class="panel" id="completion-summary">${finishSummary()}</section><details><summary>Glossary, text route and optional sources</summary><dl class="term-list"><dt>Principal</dt><dd>The starting amount invested or repaid.</dd><dt>Annual effective rate</dt><dd>The full compound growth over one year.</dd><dt>CAGR</dt><dd>The equal annual rate connecting start and end values when there are no external cash flows.</dd><dt>Present value</dt><dd>Future payments expressed at a chosen earlier date using a declared discount rate.</dd><dt>Real return</dt><dd>Return adjusted for price-level changes over the same period.</dd></dl><p><a href="guide.html">Complete printable text route</a></p><ul>${SOURCES.map(([label,url])=>`<li><a href="${url}">${label}</a></li>`).join('')}</ul><p class="mini">Sources checked 31 October 2026. External reading is optional and external sites have their own privacy policies.</p></details>`;}
function render(focus=true){let target=location.hash.slice(1);if(target==='lesson'){ $('#lesson').focus();return;}page=STEPS.some(([id])=>id===target)?target:(STEPS.some(([id])=>id===state.lastPage)?state.lastPage:'start');state.lastPage=page;$('#lesson').innerHTML=(LESSONS[page]?practice(page):({start,lab,assessment:quiz,finish}[page])())+pythonLink(2,page)+bottom();persist();document.title=`${STEPS.find(([id])=>id===page)[1]} · Chapter 2`;if(focus){$('#lesson').focus();window.scrollTo({top:0,behavior:'instant'});}}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportRecord(){download('qf-chapter-02-progress.json',JSON.stringify({chapter:2,exportedAt:new Date().toISOString(),...state,complete:complete(),notice:'Formative self-study record. Free text is self-reviewed; no credential conferred.'},null,2),'application/json');announce('Chapter 2 record exported, including all submitted practice, runs and independent attempts.');}
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-save]'))return;const id=el.name||el.id;state.fields[id]=el.type==='checkbox'?el.checked:el.value;const area=invalidate(state,id);if(id.endsWith('Criteria')&&LESSONS[id.slice(0,-8)])delete state.done[id.slice(0,-8)];if(area&&$('#feedback-'+area))$('#feedback-'+area).textContent='Work changed. Check or save this step again.';if($('#feedback-'+id))$('#feedback-'+id).textContent='Answer changed. Check it again.';persist();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
if(action==='export')exportRecord();
if(action==='setup'){if(!value('setup'))return feedback('feedback-start','Confirm that you can use the controls and find feedback or the text route.',true);state.done.start=true;persist();location.hash='returns';}
if(action==='practice'){const id=button.dataset.question,q=Object.values(PRACTICE).flat().find(q=>q.id===id),raw=value(id),ok=checkAnswer(q,raw);state.practiceAttempts.push({id,raw,correct:ok,time:new Date().toISOString()});state.checked[id]=ok;persist();const tries=state.practiceAttempts.filter(a=>a.id===id).length;feedback('feedback-'+id,ok?'Correct. '+q.why:raw===''?'Enter an answer first. Use a number without £ or %.':q.hint+(tries>1?' '+q.why:' Try the calculation again; then check your revised answer.'),!ok);}
if(action==='save-step'){const step=button.dataset.step;if(!PRACTICE[step].every(q=>state.checked[q.id]))return feedback('feedback-'+step,'Check and correct every numerical task in this step before saving.',true);if(value(step+'Reflection').trim().length<30||!value(step+'Criteria'))return feedback('feedback-'+step,'Write at least 30 characters explaining your method or correction, then confirm the self-review criterion. Length checks completeness only.',true);state.done[step]=true;persist();feedback('feedback-'+step,'Step complete. Checked calculations and your self-reviewed explanation are saved.');}
if(action==='run'){if(value('prediction').trim().length<15)return feedback('feedback-run','Write a prediction and reason (at least 15 characters) before running.',true);try{const input=Object.fromEntries(['principal','rate','inflation','years','goal'].map(id=>[id,$('#'+id).value]));const result=growthScenario(input);for(const[id,v]of Object.entries(input))state.fields[id]=v;state.runs.push({...result,prediction:value('prediction'),time:new Date().toISOString()});state.fields.handVerified=false;state.fields.hand='';delete state.done.lab;persist();render(false);feedback('feedback-run',`Run ${state.runs.length} saved. The inputs and full annual table are recorded below.`);}catch(err){feedback('feedback-run',esc(err.message),true);}}
if(action==='defaults'){Object.assign(state.fields,{principal:'1000',rate:'5',inflation:'3',years:'10',goal:'2000'});persist();render(false);$('#principal').focus();announce('Default inputs restored. Prior experiment runs are retained.');}
if(action==='hand'){const r=state.runs.at(-1);if(!r)return feedback('feedback-hand','Run the model first.',true);const ok=checkAnswer({type:'number',answer:r.nominal,tolerance:.011},value('hand'));state.fields.handVerified=ok;persist();feedback('feedback-hand',ok?'Your latest nominal ending balance matches the compound-growth calculation. Now explain the comparison and limits.':'Use the latest recorded starting amount, annual growth factor and years. Round the final answer to pennies; do not use the inflation-adjusted balance.',!ok);}
if(action==='save-lab'){if(!pairedInflationRuns(state.runs))return feedback('feedback-lab','Record two runs changing only inflation, with identical starting amount, growth rate, years and separate future payment.',true);if(!state.fields.handVerified||value('labReflection').trim().length<50)return feedback('feedback-lab','Check the latest nominal ending value, then write at least 50 characters comparing outputs and stating a limitation. Use the self-review explanation to check quality.',true);state.done.lab=true;persist();feedback('feedback-lab','Paired inflation comparison, latest hand check and reflection saved. All runs remain in your log.');}
if(action==='csv'){if(!state.runs.length)return feedback('feedback-lab','Run a comparison before exporting its data.',true);download('qf-chapter-02-runs.csv','run,principal_gbp,growth_pct,inflation_pct,years,future_payment_gbp,nominal_end_gbp,real_end_startyear_gbp,simple_end_gbp,payment_pv_gbp\n'+state.runs.map((r,i)=>[i+1,r.principal,r.rate,r.inflation,r.years,r.goal,r.nominal,r.real,r.simple,r.goalPV].join(',')).join('\n'),'text/csv');announce('All Chapter 2 runs exported as CSV.');}
if(action==='grade'){const set=Number(value('quizSet')||0)%2,qs=ASSESSMENTS[set],answers=Object.fromEntries(qs.map(q=>[q.id,value('quiz-'+q.id)]));if(qs.some(q=>String(answers[q.id]).trim()===''))return feedback('feedback-assessment','Answer all eight questions before checking. No time limit applies.',true);const result=grade(qs,answers);state.attempts.push({...result,answers,set,time:new Date().toISOString()});state.fields.quizDirty=false;delete state.done.assessment;persist();feedback('feedback-assessment',quizFeedback(state.attempts.at(-1)),!result.passed);}
if(action==='switch'){state.fields.quizSet=String((Number(value('quizSet')||0)+1)%2);for(let i=1;i<=8;i++)state.fields['quiz-a'+i]='';state.fields.quizRevision='';state.fields.quizDirty=true;delete state.done.assessment;persist();render();announce('Alternate independent case opened. Submitted attempts remain in your record.');}
if(action==='revision'){const a=state.attempts.at(-1);if(!a||a.set!==Number(value('quizSet')||0)%2||state.fields.quizDirty)return feedback('feedback-revision','Submit the current case and current answers first.',true);if(value('quizRevision').trim().length<30)return feedback('feedback-revision','Describe a specific correction or check and its reason in at least 30 characters.',true);a.revision=value('quizRevision');if(a.passed)state.done.assessment=true;persist();feedback('feedback-revision',a.passed?'Feedback response saved. Independent check complete.':'Response saved. Correct the answers and resubmit to meet the pass criteria.');}
if(action==='card'){if(!['cardMethod','cardCheck','cardLimits'].every(id=>value(id).trim().length>=30)||!value('cardCriteria'))return feedback('feedback-finish','Complete the three fields with at least 30 characters each and confirm your self-review. Specific methods and limits matter; the app checks completeness only.',true);state.card={method:value('cardMethod'),check:value('cardCheck'),limits:value('cardLimits')};state.done.finish=true;persist();render(false);feedback('feedback-finish',complete()?'Chapter 2 complete. Your calculation card and learning evidence are saved; export a copy for your records.':'Card saved. The checklist below shows any unfinished chapter evidence.');}
});
$('#chapter-select').addEventListener('change',e=>{const routes={'1':'../index.html','2':'index.html','3':'../chapter-03/','4':'../chapter-04/'};if(routes[e.target.value])location.href=routes[e.target.value];});
$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#close-privacy').addEventListener('click',()=>$('#privacy-dialog').close());
$('#reset-progress').addEventListener('click',()=>{if(!confirm('Reset only Chapter 2? This deletes its saved answers, attempts and runs from this browser. Downloaded files and Chapter 1 remain.'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();announce('Chapter 2 reset. Chapter 1 progress was not changed.');});
window.addEventListener('hashchange',()=>render());render(false);
